def _xml_error(text, exc):
    message = str(exc).split(': line ', 1)[0]
    line, col = getattr(exc, 'position', (1, 0))
    lines = text.splitlines()
    current = lines[line-1] if 0 < line <= len(lines) else ''
    prefix = current[:col]
    def result(msg, column=col+1, snippet=prefix):
        return f"line {line}, column {column}: {msg}\n -> '{snippet[-30:]}' <-- around here"
    if not text.strip():
        return "line 1, column 1: empty document\n -> '' <-- around here"
    if message == 'no element found':
        return result("'</' is required", snippet='')
    if message == 'mismatched tag':
        stack=[]
        offset=sum(len(x)+1 for x in lines[:line-1])+col
        for m in re.finditer(r'<(/?)([A-Za-z_:][\w:.-]*)\b[^>]*>', text[:offset]):
            closing,name=m.group(1),m.group(2)
            if closing:
                if stack: stack.pop()
            elif not m.group(0).rstrip().endswith('/>'):
                stack.append(name)
        expected=stack[-1] if stack else ''
        return result(f"expected end tag '{expected}'")
    if message == 'junk after document element':
        return result('extra content at document end')
    if message == 'not well-formed (invalid token)':
        if prefix and re.search(r'<[^>]*\s+[A-Za-z_:][\w:.-]*\s*$',prefix):
            return result("'=' was required here")
        if prefix.rstrip().endswith('='):
            bad=current[col:col+1] or ''
            return result(f"string not started (got {bad!r})")
    if message == 'unclosed token':
        if re.search(r'<[A-Za-z_:][\w:.-]*\s+[^>]*=[\"\'][^\"\']*$', text):
            return result('string not closed', column=len(current)+1, snippet='')
        if re.fullmatch(r'<[A-Za-z_:][\w:.-]*', text.strip()):
            return result("failed to parse QName ''", column=len(current)+1, snippet='')
    return str(exc)


